// Types for `?medkit` imports. Add "@medkitjs/vite/client" to "types" in
// tsconfig.json, or reference it from a .d.ts file.

declare module '*.jpg?medkit' {
  const manifest: import('@medkitjs/elements').ImageManifest;
  export default manifest;
}
